def spl(success, shortest, taken):
    """success: List[0/1]; shortest/taken: List[float] 路径长度"""
    assert len(success) == len(shortest) == len(taken) > 0
    total = 0.0
    for s, l, p in zip(success, shortest, taken):
        if s and l > 0:
            total += l / max(p, l)   # 成功且不绕路才拿满分
    return total / len(success)

# 例：spl([1, 1, 0], [10.0, 8.0, 5.0], [10.0, 16.0, 20.0]) -> 0.5
